host_boundary_queries.sql:
SELECT d.id AS device_id,d.name AS device_name,h.id AS host_id,h.name AS host_name,h.parent_id,
(h.ts-3762433098211544)/1e6 host_start_ms,h.dur/1e6 host_dur_ms
FROM thread_slice d JOIN flow f ON f.slice_in=d.id JOIN thread_slice h ON h.id=f.slice_out WHERE d.id IN (43469,43476,43485);
